import socket, struct

def fcg_encode(name, val):
    def pair(k, v):
        out=b''
        for n in (len(k), len(v)):
            if n < 128: out += bytes([n])
            else: out += struct.pack('>I', n | 0x80000000)
        return out
    return pair(name.encode(), val.encode()) + name.encode() + val.encode()

def build(params, path):
    body = b'\x01\x01\x00\x01\x00\x08\x00\x00' + b'\x00\x00\x00\x00\x00\x00\x00\x00'
