    for k,v in params.items():
        kv = fcg_encode(k,v)
        pb += kv
    body += b'\x01\x04' + struct.pack('>H', len(pb))[:1] + b'\x00' + struct.pack('>H', len(pb))[1:] + b'\x00\x00' + pb + b'\x01\x04\x00\x00\x00\x00\x00' + b'\x01\x05\x00\x00\x00\x00\x00'
